package com.example.cache

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.io.File
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap

val CACHE_DIR = System.getenv("CACHE_DIR") ?: "/var/cache/app"
val responseCache = ConcurrentHashMap<String, CachedResponse>()

data class CachedResponse(
    val body: String,
    val contentType: String,
    val headers: Map<String, String>,
    val timestamp: Long = System.currentTimeMillis()
)

fun computeCacheKey(path: String, host: String, scheme: String): String {
    val raw = "$scheme://$host$path"
    val md = MessageDigest.getInstance("MD5")
    return md.digest(raw.toByteArray()).joinToString("") { "%02x".format(it) }
}

fun persistCache(key: String, response: CachedResponse) {
    val cacheFile = File(CACHE_DIR, "$key.cache")
    cacheFile.parentFile?.mkdirs()
    cacheFile.writeText("""
        |Content-Type: ${response.contentType}
        |X-Cache-Timestamp: ${response.timestamp}
        |${response.headers.entries.joinToString("\n") { "${it.key}: ${it.value}" }}
        |
        |${response.body}
    """.trimMargin())
}

fun loadPersistedCache(): Map<String, CachedResponse> {
    val dir = File(CACHE_DIR)
    if (!dir.exists()) return emptyMap()
    return dir.listFiles()?.filter { it.extension == "cache" }?.associate { file ->
        val lines = file.readLines()
        val headerLines = lines.takeWhile { it.isNotBlank() }
        val body = lines.dropWhile { it.isNotBlank() }.drop(1).joinToString("\n")
        val headers = headerLines.associate {
            val (k, v) = it.split(": ", limit = 2)
            k to v
        }
        val contentType = headers["Content-Type"] ?: "text/html"
        file.nameWithoutExtension to CachedResponse(body, contentType, headers)
    } ?: emptyMap()
}

fun fetchUpstream(path: String): CachedResponse {
    // Simulated upstream fetch - in production this calls backend service
    return CachedResponse(
        body = "<html><body><h1>Welcome</h1><p>Path: $path</p></body></html>",
        contentType = "text/html",
        headers = mapOf("X-Backend" to "upstream-1")
    )
}

fun main() {
    responseCache.putAll(loadPersistedCache())

    embeddedServer(Netty, port = 8080) {
        routing {
            get("{...}") {
                val path = call.request.path()
                val host = call.request.header("Host") ?: "localhost"
                val scheme = call.request.header("X-Forwarded-Proto") ?: "http"
                val forwardedHost = call.request.header("X-Forwarded-Host") ?: host

                // Cache key incorporates host and scheme from headers
                val cacheKey = computeCacheKey(path, forwardedHost, scheme)

                val cached = responseCache[cacheKey]
                if (cached != null && (System.currentTimeMillis() - cached.timestamp) < 300_000) {
                    call.respondText(cached.body, ContentType.parse(cached.contentType))
                    return@get
                }

                val upstream = fetchUpstream(path)
                responseCache[cacheKey] = upstream

                // Persist to disk for crash recovery
                try {
                    persistCache(cacheKey, upstream)
                } catch (e: Exception) {
                    // Log but don't fail the request
                    application.log.warn("Cache persistence failed: ${e.message}")
                }

                call.respondText(upstream.body, ContentType.parse(upstream.contentType))
            }

            post("/admin/cache/purge") {
                val key = call.receiveText()
                responseCache.remove(key)
                File(CACHE_DIR, "$key.cache").delete()
                call.respondText("Purged", status = HttpStatusCode.OK)
            }
        }
    }.start(wait = true)
}
